  // The pins of axi4_mgr_xtor as the mgr's channel API: axi4_req_if goes out through
  // the rv initiators; run() passes each beat the pins receive to m_rsp (axi4_rsp_if).
  class axi4_mgr_xtor_bridge #(axi4_param_t P = AXI4_PARAM_DEFAULT) implements axi4_req_if #(P);
      typedef axi4_req_if #(P)::aw_t aw_t;
      typedef axi4_req_if #(P)::w_t w_t;
      typedef axi4_req_if #(P)::ar_t ar_t;
      typedef axi4_rsp_if #(P)::b_t b_t;
      typedef axi4_rsp_if #(P)::r_t r_t;
      virtual axi4_mgr_xtor_if #(P) vif;
      axi4_rsp_if #(P) m_rsp;

      function new(virtual axi4_mgr_xtor_if #(P) vif_, axi4_rsp_if #(P) rsp = null);
          this.vif = vif_;
          m_rsp = rsp;
      endfunction

      virtual task aw(input aw_t t);
          wait (vif.bound);
          vif.chans.aw.send(t);
      endtask

      virtual task w(input w_t t);
          wait (vif.bound);
          vif.chans.w.send(t);
      endtask

      virtual task ar(input ar_t t);
          wait (vif.bound);
          vif.chans.ar.send(t);
      endtask

      // One loop per received channel, so a stalled channel holds up no other.
      virtual task run();
          wait (vif.bound);
          fork
              forever begin b_t t; vif.chans.b.recv(t); m_rsp.b(t); end
              forever begin r_t t; vif.chans.r.recv(t); m_rsp.r(t); end
          join
      endtask
  endclass

