      endtask

      virtual task r(input r_t t);
          wait (vif.bound);
          vif.chans.r.send(t);
      endtask

      // One loop per received channel, so a stalled channel holds up no other.
      virtual task run();
          wait (vif.bound);
          fork
              forever begin aw_t t; vif.chans.aw.recv(t); m_req.aw(t); end
              forever begin w_t t; vif.chans.w.recv(t); m_req.w(t); end
