  // What axi4_mon_xtor sees, as listener calls: <ch>_pre on the first valid
  // cycle of a beat, <ch>_post on its handshake. Add listeners to req and rsp.
  class axi4_mon_xtor_bridge #(axi4_param_t P = AXI4_PARAM_DEFAULT);
      typedef axi4_req_if #(P)::aw_t aw_t;
      typedef axi4_req_if #(P)::w_t w_t;
      typedef axi4_rsp_if #(P)::b_t b_t;
      typedef axi4_req_if #(P)::ar_t ar_t;
      typedef axi4_rsp_if #(P)::r_t r_t;
      virtual axi4_mon_xtor_if #(P) vif;
      axi4_req_if_listener_fanout #(P) req = new();
      axi4_rsp_if_listener_fanout #(P) rsp = new();

      function new(virtual axi4_mon_xtor_if #(P) vif_);
          this.vif = vif_;
      endfunction

      virtual task run();
          wait (vif.bound);
          fork
              forever begin
                  aw_t t;
                  bit first, xfer;
                  vif.chans.aw.get_ev(t, first, xfer);
                  if (first) req.aw_pre(t);
                  if (xfer) req.aw_post(t);
              end
              forever begin
                  w_t t;
                  bit first, xfer;
                  vif.chans.w.get_ev(t, first, xfer);
                  if (first) req.w_pre(t);
                  if (xfer) req.w_post(t);
              end
              forever begin
                  b_t t;
                  bit first, xfer;
                  vif.chans.b.get_ev(t, first, xfer);
                  if (first) rsp.b_pre(t);
                  if (xfer) rsp.b_post(t);
              end
              forever begin
                  ar_t t;
                  bit first, xfer;
                  vif.chans.ar.get_ev(t, first, xfer);
                  if (first) req.ar_pre(t);
                  if (xfer) req.ar_post(t);
              end
              forever begin
                  r_t t;
                  bit first, xfer;
                  vif.chans.r.get_ev(t, first, xfer);
                  if (first) rsp.r_pre(t);
                  if (xfer) rsp.r_post(t);
              end
          join
      endtask
  endclass

  // The mgr's API endpoint on a component: calls axi4_req_if, provides axi4_rsp_if. Its peer
