  // Listeners attached by path to the abstractor handles of this P. A test
  // registers listeners for a path (add; either may be null); each handle
  // registers its proxies under its path when it is built (attach). Whichever
  // comes second joins them, so the order does not matter as long as both come
  // before the traffic. unused() names the listener paths no handle took (a
  // misspelled path, another P).
  class axi4_observers #(axi4_param_t P = AXI4_PARAM_DEFAULT);
      static string m_path[$];
      static axi4_req_if_listener #(P) m_req[$];
      static axi4_rsp_if_listener #(P) m_rsp[$];
      static bit m_used[$];
      static string m_h_path[$];
      static axi4_req_if_proxy #(P) m_h_req[$];
      static axi4_rsp_if_proxy #(P) m_h_rsp[$];

      static function void pair(int unsigned i, axi4_req_if_proxy #(P) req, axi4_rsp_if_proxy #(P) rsp);
          if (m_req[i] != null) req.add_listener(m_req[i]);
          if (m_rsp[i] != null) rsp.add_listener(m_rsp[i]);
          m_used[i] = 1;
      endfunction

      static function void add(string path, axi4_req_if_listener #(P) req, axi4_rsp_if_listener #(P) rsp);
          m_path.push_back(path);
          m_req.push_back(req);
          m_rsp.push_back(rsp);
          m_used.push_back(0);
          foreach (m_h_path[h]) if (m_h_path[h] == path)
              pair(m_path.size() - 1, m_h_req[h], m_h_rsp[h]);
      endfunction

      static function void attach(string path, axi4_req_if_proxy #(P) req, axi4_rsp_if_proxy #(P) rsp);
          m_h_path.push_back(path);
          m_h_req.push_back(req);
          m_h_rsp.push_back(rsp);
          foreach (m_path[i]) if (m_path[i] == path) pair(i, req, rsp);
      endfunction

      // The listener paths no handle has taken, comma-separated; "" if none.
      static function string unused();
          string s;
          foreach (m_path[i]) if (!m_used[i]) s = {s, (s == "") ? "" : ", ", m_path[i]};
          return s;
      endfunction
  endclass

