      virtual task b(input b_t t);
          @m_never;
      endtask

      virtual task r(input r_t t);
          @m_never;
      endtask

      virtual function fw_sp_base pin_sp(); return sp; endfunction
      virtual function string xtor_module(); return "axi4_sub_xtor"; endfunction
      virtual function string vif_type();
          return {"virtual axi4_sub_xtor_if #(", sp.param_lit(), ")"};
      endfunction
      virtual function string handle_type();
          return {"axi4_sub_abs_h #(", sp.param_lit(), ")"};
      endfunction
  endclass
  /* verilator lint_on UNUSEDSIGNAL */

  // Run time: the abstractor axi4_mgr_abs, as a component. Calls made on the
  // endpoint go through req to the pins (axi4_mgr_xtor_bridge); what the pins receive goes
  // through rsp to the endpoint's peer. Listeners attach to req and rsp.
  // Knobs set for its path in fw_proto_cfg ("<ch>.depth", "<ch>.max_gap")
  // reach the channel transactors when it starts. Listeners registered for its
  // path (axi4_observers) are added to its proxies.
  class axi4_mgr_abs_h #(axi4_param_t P = AXI4_PARAM_DEFAULT) extends fw_component implements fw_runnable;
      axi4_mgr_xtor_bridge #(P) bridge;
      axi4_req_if_proxy #(P) req;
      axi4_rsp_if_proxy #(P) rsp;
      axi4_sub_socket #(P) m_ep;

      function new(string name, fw_component parent, virtual axi4_mgr_xtor_if #(P) vif);
          super.new(name, parent);
          rsp = new();
          bridge = new(vif, rsp);
          req = new(bridge);
          axi4_observers #(P)::attach(fw_rel_path(this), req, rsp);
          parent.add_runnable(this);
      endfunction

      function void serve(axi4_sub_socket #(P) ep);
          m_ep = ep;
          ep.set_imp(req);
      endfunction

      virtual task run();
          string path = fw_rel_path(this);
          string names[$];
          rsp.m_target = m_ep.t;
          wait (bridge.vif.bound);
          fw_proto_cfg::names(path, names);
          foreach (names[i])
              if (!bridge.vif.chans.set_knob(names[i], fw_proto_cfg::get_int(path, names[i], 0)))
                  $error("%s: no knob '%s'", path, names[i]);
          bridge.run();
      endtask
  endclass

